try (JMSContext ctx = cf.createContext(JMSContext.SESSION_TRANSACTED)) {
    JMSProducer p = ctx.createProducer().setDeliveryMode(DeliveryMode.PERSISTENT);
    p.send(orderQueue, order);
    ctx.commit();                       // ack: the provider now owns the message
}
// receive side: ack only after the business commit
try (JMSContext ctx = cf.createContext(JMSContext.CLIENT_ACKNOWLEDGE)) {
    Message m = ctx.createConsumer(orderQueue).receive();
    placeOrder(m);                      // business effect first
    m.acknowledge();                    // then the delivery ack
}

