@Resource(lookup = "java:/JmsXA") ConnectionFactory xaCf;
@Resource MessageDrivenContext ctx;

@TransactionAttribute(TransactionAttributeType.REQUIRED)
public void placeOrder(Order o) {
    em.persist(o);                       // same XA transaction
    try (JMSContext c = xaCf.createContext(JMSContext.SESSION_TRANSACTED)) {
        c.createProducer().send(orderQueue, o.asMessage());
    }                                    // container commit: both, or neither
}

